def hexadecimal_and_base36_power_string(n):
    chars='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    def convert(value,base):
        answer=''
        while value:
            answer=chars[value%base]+answer
            value//=base
        return answer or '0'
    return convert(n*n,16)+convert(n*n*n,36)

